"""Local-filesystem FileStore. Keys are generated by the server (never taken from users), so a path can't be steered."""
import re
from pathlib import Path

from core.connectors.base import ConnectorInfo

_KEY = re.compile(r"^[a-f0-9]{16,64}$")


class LocalFileStore:
    def __init__(self, root: Path):
        self.root = Path(root)

    def info(self) -> ConnectorInfo:
        return ConnectorInfo(id="files", kind="file_store", name="Local file store", mode="local", enabled=True,
                             description="Files are kept on this server's disk.", detail={"root": "configured server directory"})

    def _path(self, key: str) -> Path:
        if not _KEY.match(key):
            raise ValueError("invalid storage key")
        return self.root / key[:2] / key

    def put(self, key: str, data: bytes) -> None:
        p = self._path(key)
        p.parent.mkdir(parents=True, exist_ok=True)
        tmp = p.with_suffix(".tmp")
        tmp.write_bytes(data)
        tmp.replace(p)   # atomic: a reader never sees a half-written file

    def get(self, key: str) -> bytes:
        return self._path(key).read_bytes()

    def delete(self, key: str) -> None:
        self._path(key).unlink(missing_ok=True)
